from __future__ import annotations

from pathlib import Path


def once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f"release feature anchor not found: {label}")
    return text.replace(old, new, 1)


def patch_db() -> None:
    p=Path('jewel_server/db.py');t=p.read_text(encoding='utf-8')
    t=once(t,'LATEST_SCHEMA_VERSION = 4','LATEST_SCHEMA_VERSION = 5','schema version')
    migration='''\n\ndef _migration_5(conn) -> None:\n    _add_column_if_missing(conn, "customers", "balance_paise", "INTEGER NOT NULL DEFAULT 0")\n    _add_column_if_missing(conn, "suppliers", "balance_paise", "INTEGER NOT NULL DEFAULT 0")\n    _add_column_if_missing(conn, "karigars", "cash_balance_paise", "INTEGER NOT NULL DEFAULT 0")\n    _add_column_if_missing(conn, "karigars", "metal_balance_mg", "INTEGER NOT NULL DEFAULT 0")\n    conn.execute("UPDATE customers SET balance_paise=CAST(ROUND(balance*100) AS INTEGER)")\n    conn.execute("UPDATE suppliers SET balance_paise=CAST(ROUND(balance*100) AS INTEGER)")\n    conn.execute("UPDATE karigars SET cash_balance_paise=CAST(ROUND(cash_balance*100) AS INTEGER),metal_balance_mg=CAST(ROUND(metal_balance_grams*1000) AS INTEGER)")\n    conn.executescript(r"""\n    CREATE TABLE IF NOT EXISTS sale_returns (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      return_no TEXT NOT NULL UNIQUE,\n      client_request_id TEXT UNIQUE,\n      sale_id INTEGER NOT NULL REFERENCES sales(id),\n      customer_id INTEGER REFERENCES customers(id),\n      branch_id INTEGER NOT NULL REFERENCES branches(id),\n      business_date TEXT NOT NULL,\n      taxable_paise INTEGER NOT NULL CHECK(taxable_paise>=0),\n      gst_paise INTEGER NOT NULL CHECK(gst_paise>=0),\n      cgst_paise INTEGER NOT NULL DEFAULT 0 CHECK(cgst_paise>=0),\n      sgst_paise INTEGER NOT NULL DEFAULT 0 CHECK(sgst_paise>=0),\n      igst_paise INTEGER NOT NULL DEFAULT 0 CHECK(igst_paise>=0),\n      round_off_paise INTEGER NOT NULL DEFAULT 0,\n      total_paise INTEGER NOT NULL CHECK(total_paise>=0),\n      refund_cash_paise INTEGER NOT NULL DEFAULT 0 CHECK(refund_cash_paise>=0),\n      refund_card_paise INTEGER NOT NULL DEFAULT 0 CHECK(refund_card_paise>=0),\n      refund_upi_paise INTEGER NOT NULL DEFAULT 0 CHECK(refund_upi_paise>=0),\n      refund_credit_paise INTEGER NOT NULL DEFAULT 0 CHECK(refund_credit_paise>=0),\n      reason TEXT NOT NULL,\n      status TEXT NOT NULL DEFAULT 'posted' CHECK(status IN ('posted','cancelled')),\n      user_id INTEGER NOT NULL REFERENCES users(id),\n      created_at TEXT NOT NULL,\n      cancelled_at TEXT,\n      cancelled_by INTEGER REFERENCES users(id),\n      CHECK(cgst_paise+sgst_paise+igst_paise=gst_paise),\n      CHECK(refund_cash_paise+refund_card_paise+refund_upi_paise+refund_credit_paise=total_paise)\n    );\n    CREATE INDEX IF NOT EXISTS idx_sale_returns_sale ON sale_returns(sale_id,id);\n    CREATE INDEX IF NOT EXISTS idx_sale_returns_date ON sale_returns(business_date,id);\n    CREATE TABLE IF NOT EXISTS sale_return_items (\n      id INTEGER PRIMARY KEY AUTOINCREMENT,\n      return_id INTEGER NOT NULL REFERENCES sale_returns(id),\n      sale_item_id INTEGER NOT NULL REFERENCES sale_items(id),\n      item_id INTEGER NOT NULL REFERENCES items(id),\n      tag_no TEXT NOT NULL,\n      taxable_paise INTEGER NOT NULL CHECK(taxable_paise>=0),\n      gst_amount_paise INTEGER NOT NULL CHECK(gst_amount_paise>=0),\n      round_off_paise INTEGER NOT NULL DEFAULT 0,\n      line_total_paise INTEGER NOT NULL CHECK(line_total_paise>=0),\n      cost_amount_paise INTEGER NOT NULL DEFAULT 0 CHECK(cost_amount_paise>=0),\n      active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1))\n    );\n    CREATE INDEX IF NOT EXISTS idx_sale_return_items_return ON sale_return_items(return_id,id);\n    CREATE UNIQUE INDEX IF NOT EXISTS uq_sale_return_item_active ON sale_return_items(sale_item_id) WHERE active=1;\n\n    CREATE TRIGGER IF NOT EXISTS canonical_customer_balance_insert BEFORE INSERT ON customers\n    WHEN NEW.balance_paise!=CAST(ROUND(NEW.balance*100) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'customer balance mirror mismatch'); END;\n    CREATE TRIGGER IF NOT EXISTS canonical_customer_balance_update BEFORE UPDATE OF balance,balance_paise ON customers\n    WHEN NEW.balance_paise!=CAST(ROUND(NEW.balance*100) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'customer balance mirror mismatch'); END;\n    CREATE TRIGGER IF NOT EXISTS canonical_supplier_balance_insert BEFORE INSERT ON suppliers\n    WHEN NEW.balance_paise!=CAST(ROUND(NEW.balance*100) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'supplier balance mirror mismatch'); END;\n    CREATE TRIGGER IF NOT EXISTS canonical_supplier_balance_update BEFORE UPDATE OF balance,balance_paise ON suppliers\n    WHEN NEW.balance_paise!=CAST(ROUND(NEW.balance*100) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'supplier balance mirror mismatch'); END;\n    CREATE TRIGGER IF NOT EXISTS canonical_karigar_balance_insert BEFORE INSERT ON karigars\n    WHEN NEW.cash_balance_paise!=CAST(ROUND(NEW.cash_balance*100) AS INTEGER) OR NEW.metal_balance_mg!=CAST(ROUND(NEW.metal_balance_grams*1000) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'karigar balance mirror mismatch'); END;\n    CREATE TRIGGER IF NOT EXISTS canonical_karigar_balance_update BEFORE UPDATE OF cash_balance,cash_balance_paise,metal_balance_grams,metal_balance_mg ON karigars\n    WHEN NEW.cash_balance_paise!=CAST(ROUND(NEW.cash_balance*100) AS INTEGER) OR NEW.metal_balance_mg!=CAST(ROUND(NEW.metal_balance_grams*1000) AS INTEGER)\n    BEGIN SELECT RAISE(ABORT,'karigar balance mirror mismatch'); END;\n\n    CREATE TRIGGER IF NOT EXISTS sale_returns_financial_no_update BEFORE UPDATE OF\n      return_no,client_request_id,sale_id,customer_id,branch_id,business_date,taxable_paise,gst_paise,cgst_paise,sgst_paise,igst_paise,round_off_paise,total_paise,refund_cash_paise,refund_card_paise,refund_upi_paise,refund_credit_paise,reason,user_id,created_at\n      ON sale_returns BEGIN SELECT RAISE(ABORT,'posted credit-note financial fields are immutable'); END;\n    CREATE TRIGGER IF NOT EXISTS sale_returns_no_delete BEFORE DELETE ON sale_returns\n      BEGIN SELECT RAISE(ABORT,'credit notes cannot be deleted; cancel/reverse instead'); END;\n    CREATE TRIGGER IF NOT EXISTS sale_return_items_financial_no_update BEFORE UPDATE OF\n      return_id,sale_item_id,item_id,tag_no,taxable_paise,gst_amount_paise,round_off_paise,line_total_paise,cost_amount_paise\n      ON sale_return_items BEGIN SELECT RAISE(ABORT,'posted credit-note lines are immutable'); END;\n    CREATE TRIGGER IF NOT EXISTS sale_return_items_no_delete BEFORE DELETE ON sale_return_items\n      BEGIN SELECT RAISE(ABORT,'credit-note lines cannot be deleted'); END;\n    """)\n    main_branch = conn.execute("SELECT id FROM branches WHERE code='MAIN'").fetchone()\n    if main_branch:\n        bid=int(main_branch[0])\n        if conn.execute("SELECT 1 FROM counters WHERE branch_id=? AND name='Main Counter'",(bid,)).fetchone() and not conn.execute("SELECT 1 FROM counters WHERE branch_id=? AND name='Counter 1'",(bid,)).fetchone():\n            conn.execute("UPDATE counters SET name='Counter 1' WHERE branch_id=? AND name='Main Counter'",(bid,))\n        conn.execute("INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 1',1)",(bid,))\n        conn.execute("INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 2',1)",(bid,))\n        conn.execute("INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 3',1)",(bid,))\n        conn.execute("UPDATE branches SET name='Bijoria Main Showroom' WHERE id=? AND name='Main Showroom'",(bid,))\n    conn.execute("UPDATE settings SET value='Bijoria',updated_at=? WHERE key='business_name' AND value='My Jewellery Store'",(utcnow(),))\n    conn.execute("UPDATE settings SET value='36',updated_at=? WHERE key='business_state_code' AND trim(value)=''",(utcnow(),))\n    conn.execute("INSERT OR IGNORE INTO sequences(name,value) VALUES('return',0)")\n'''
    t=once(t,'\n\nMIGRATIONS = ((1, _migration_1), (2, _migration_2), (3, _migration_3), (4, _migration_4))',migration+'\n\nMIGRATIONS = ((1, _migration_1), (2, _migration_2), (3, _migration_3), (4, _migration_4), (5, _migration_5))','migration table')
    t=once(t,"conn.execute(\"INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Main Counter',1)\",(branch_id,))","conn.execute(\"INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 1',1)\",(branch_id,)); conn.execute(\"INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 2',1)\",(branch_id,)); conn.execute(\"INSERT OR IGNORE INTO counters(branch_id,name,active) VALUES(?,'Counter 3',1)\",(branch_id,))",'fresh counters')
    t=once(t,'defaults={"business_name":"My Jewellery Store"','defaults={"business_name":"Bijoria"','business default')
    t=once(t,'"business_state_code":""','"business_state_code":"36"','state default')
    t=once(t,'("invoice","purchase","customer","supplier","karigar","repair","order","approval","audit","journal","tag")','("invoice","purchase","return","customer","supplier","karigar","repair","order","approval","audit","journal","tag")','return sequence')
    p.write_text(t,encoding='utf-8')


def patch_services() -> None:
    p=Path('jewel_server/services.py');t=p.read_text(encoding='utf-8')
    t=once(t,"if cid and credit:conn.execute('UPDATE customers SET balance=balance+?,updated_at=? WHERE id=?',(credit,now,cid))","if cid and credit:\n        row=c.execute('SELECT balance_paise FROM customers WHERE id=?',(cid,)).fetchone();newp=int(row['balance_paise'] or 0)+money_paise(credit);c.execute('UPDATE customers SET balance=?,balance_paise=?,updated_at=? WHERE id=?',(money(newp/100),newp,now,cid))",'sale customer balance')
    t=once(t,"if sale['customer_id'] and sale['payment_credit']:conn.execute('UPDATE customers SET balance=balance-?,updated_at=? WHERE id=?',(sale['payment_credit'],now,sale['customer_id']))","if sale['customer_id'] and sale['payment_credit']:\n        row=conn.execute('SELECT balance_paise FROM customers WHERE id=?',(sale['customer_id'],)).fetchone();newp=int(row['balance_paise'] or 0)-money_paise(sale['payment_credit']);conn.execute('UPDATE customers SET balance=?,balance_paise=?,updated_at=? WHERE id=?',(money(newp/100),newp,now,sale['customer_id']))",'cancel customer balance')
    p.write_text(t,encoding='utf-8')


def patch_security() -> None:
    p=Path('jewel_server/security.py');t=p.read_text(encoding='utf-8')
    t=once(t,'        "sales",\n        "contacts",','        "sales",\n        "returns",\n        "contacts",','manager returns permission')
    p.write_text(t,encoding='utf-8')


def patch_main() -> None:
    p=Path('jewel_server/main.py');t=p.read_text(encoding='utf-8')
    t=once(t,'from .services import cancel_sale,create_item,latest_rate,money,post_sale,purity_fraction,quote_sale,transfer_item,update_item,weight','from .services import cancel_sale,create_item,latest_rate,money,post_sale,purity_fraction,quote_sale,transfer_item,update_item,weight\nfrom .returns import cancel_sale_return,list_returns,post_sale_return,return_detail','return imports')
    anchor="""@app.post('/api/sales/{sid}/cancel')\ndef sale_cancel(sid:int,req:Request,p:dict=Body(default={}),u=Depends(require('sales'))):\n    if u['role'] not in ('admin','manager'):raise HTTPException(403,'Manager permission required to cancel invoices')\n    with write_db() as c:return cancel_sale(c,sid,u,str(p.get('reason') or 'Cancelled'),ip(req))\n"""
    addition=anchor+"""\n@app.get('/api/returns')\ndef returns_list(limit:int=Query(500,le=2000),u=Depends(require('returns'))):\n    with read_db() as c:return list_returns(c,limit)\n@app.get('/api/returns/{rid}')\ndef returns_detail(rid:int,u=Depends(require('returns'))):\n    with read_db() as c:return return_detail(c,rid)\n@app.post('/api/sales/{sid}/return')\ndef sales_return(sid:int,req:Request,p:dict=Body(...),u=Depends(require('returns'))):\n    with write_db() as c:return post_sale_return(c,sid,p,u,ip(req))\n@app.post('/api/returns/{rid}/cancel')\ndef returns_cancel(rid:int,req:Request,p:dict=Body(default={}),u=Depends(require('returns'))):\n    with write_db() as c:return cancel_sale_return(c,rid,u,str(p.get('reason') or ''),ip(req))\n"""
    t=once(t,anchor,addition,'return endpoints')
    t=once(t,"if sid and payable:c.execute('UPDATE suppliers SET balance=balance+?,updated_at=? WHERE id=?',(payable,now,sid))","if sid and payable:\n            row=c.execute('SELECT balance_paise FROM suppliers WHERE id=?',(sid,)).fetchone();newp=int(row['balance_paise'] or 0)+money_paise(payable);c.execute('UPDATE suppliers SET balance=?,balance_paise=?,updated_at=? WHERE id=?',(money(newp/100),newp,now,sid))",'supplier balance')
    old="md=wt if typ=='metal_issue' else -wt if typ=='metal_receive' else 0;cd=amt if typ in ('cash_debit','making_charge') else -amt if typ=='cash_credit' else 0;c.execute('UPDATE karigars SET metal_balance_grams=metal_balance_grams+?,cash_balance=cash_balance+?,updated_at=? WHERE id=?',(md,cd,utcnow(),kid));return {'id':cur.lastrowid}"
    new="md=wt if typ=='metal_issue' else -wt if typ=='metal_receive' else 0;cd=amt if typ in ('cash_debit','making_charge') else -amt if typ=='cash_credit' else 0;row=c.execute('SELECT metal_balance_mg,cash_balance_paise FROM karigars WHERE id=?',(kid,)).fetchone();newmg=int(row['metal_balance_mg'] or 0)+int(round(md*1000));newp=int(row['cash_balance_paise'] or 0)+money_paise(cd);c.execute('UPDATE karigars SET metal_balance_grams=?,metal_balance_mg=?,cash_balance=?,cash_balance_paise=?,updated_at=? WHERE id=?',(newmg/1000.0,newmg,money(newp/100),newp,utcnow(),kid));return {'id':cur.lastrowid}"
    t=once(t,old,new,'karigar mirrors')
    p.write_text(t,encoding='utf-8')


def patch_tally() -> None:
    p=Path('jewel_server/tally.py');t=p.read_text(encoding='utf-8')
    anchor='''    if typ == "purchase":\n'''
    block='''    if typ in {"sale_return", "sale_return_cogs"}:\n        ret_row = conn.execute("SELECT * FROM sale_returns WHERE id=?", (entity_id,)).fetchone()\n        if not ret_row:\n            raise TallySyncError(f"Sales return {entity_id} no longer exists")\n        ret = dict(ret_row)\n        sale_row = conn.execute("SELECT * FROM sales WHERE id=?", (ret["sale_id"],)).fetchone()\n        sale = dict(sale_row) if sale_row else {}\n        customer_row = conn.execute("SELECT * FROM customers WHERE id=?", (ret["customer_id"],)).fetchone() if ret.get("customer_id") else None\n        customer = dict(customer_row) if customer_row else None\n        if typ == "sale_return":\n            entries: list[dict[str, Any]] = []\n            party_names: set[str] = set()\n            taxable=qmoney(Decimal(int(ret["taxable_paise"]))/100)\n            gst=qmoney(Decimal(int(ret["gst_paise"]))/100)\n            if taxable: entries.append({"ledger":_mapping(mappings,"sales"),"amount":taxable,"debit":True})\n            for key,mapkey in (("cgst_paise","cgst"),("sgst_paise","sgst"),("igst_paise","igst")):\n                value=qmoney(Decimal(int(ret[key] or 0))/100)\n                if value: entries.append({"ledger":_mapping(mappings,mapkey),"amount":value,"debit":True})\n            ro=qmoney(Decimal(int(ret["round_off_paise"] or 0))/100)\n            if ro: entries.append({"ledger":_mapping(mappings,"round_off"),"amount":abs(ro),"debit":ro>0})\n            cash=qmoney(Decimal(int(ret["refund_cash_paise"] or 0))/100)\n            bank=qmoney(Decimal(int(ret["refund_card_paise"] or 0)+int(ret["refund_upi_paise"] or 0))/100)\n            credit=qmoney(Decimal(int(ret["refund_credit_paise"] or 0))/100)\n            if cash: entries.append({"ledger":_mapping(mappings,"cash"),"amount":cash,"debit":False})\n            if bank: entries.append({"ledger":_mapping(mappings,"bank"),"amount":bank,"debit":False})\n            if credit:\n                if not customer: raise TallySyncError("Customer-account sales return has no customer")\n                party_name=str(customer["name"]);party_names.add(party_name);party_to_create.append((customer,"Sundry Debtors"))\n                entries.append({"ledger":party_name,"amount":credit,"debit":False,"party":True,"bill_ref":sale.get("invoice_no") or ret["return_no"],"bill_type":"Agst Ref"})\n            xml=build_voucher_xml(company=company,voucher_type="Credit Note",voucher_number=ret["return_no"],date=_voucher_date(ret["business_date"]),remote_id=row["remote_id"],entries=entries,narration=f"JewelLAN sales return {ret['return_no']} against {sale.get('invoice_no','')}",action="Cancel" if op=="cancel" else "Create")\n            return xml,_required_static_ledgers(entries,party_names),party_to_create\n        cost_paise=conn.execute("SELECT coalesce(sum(cost_amount_paise),0) v FROM sale_return_items WHERE return_id=?",(entity_id,)).fetchone()["v"]\n        cost=qmoney(Decimal(int(cost_paise or 0))/100)\n        entries=[{"ledger":_mapping(mappings,"inventory"),"amount":cost,"debit":True},{"ledger":_mapping(mappings,"cogs"),"amount":cost,"debit":False}]\n        xml=build_voucher_xml(company=company,voucher_type="Journal",voucher_number=f"{ret['return_no']}-COGS",date=_voucher_date(ret["business_date"]),remote_id=row["remote_id"],entries=entries,narration=f"Restore jewellery cost on {ret['return_no']}",action="Cancel" if op=="cancel" else "Create")\n        return xml,_required_static_ledgers(entries,set()),[]\n\n'''
    t=once(t,anchor,block+anchor,'Tally returns')
    p.write_text(t,encoding='utf-8')


if __name__=='__main__':
    patch_db();patch_services();patch_security();patch_main();patch_tally();print('production release features applied')
